  else rules=$(jq -c --argjson c "$contexts" '. + [{type: "required_status_checks", parameters: {strict_required_status_checks_policy: false, required_status_checks: $c}}]' <<<'[{"type":"pull_request","parameters":{"required_approving_review_count":1,"dismiss_stale_reviews_on_push":false,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"non_fast_forward"}]'); fi
  bot=$(pushes '.github' 'main'); [ "$bot" = true ] || bot=false; [ "$bot" = false ] || echo "UOR-Foundation/.github: GitHub Actions pushes to the default branch, so it may bypass" >&2
  jq -c --argjson r "$rules" --argjson bot "$bot" '.rules = $r | if $bot then .bypass_actors += [{actor_id: 15368, actor_type: "Integration", bypass_mode: "always"}] else . end' <<<'{"name":"governance-6.2-t3","target":"branch","enforcement":"active","conditions":{"ref_name":{"include":["~DEFAULT_BRANCH"],"exclude":[]}},"rules":[{"type":"pull_request","parameters":{"required_approving_review_count":1,"dismiss_stale_reviews_on_push":false,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"non_fast_forward"}],"bypass_actors":[{"actor_id":1,"actor_type":"OrganizationAdmin","bypass_mode":"always"}]}' | ruleset '.github' 'governance-6.2-t3'
